/// `USHL_asisdsame_only`.
///
/// Cut: ENV, V_read, V_set.
pub(super) fn USHL_asisdsame_only(
    word: u32,
    b: &mut Builder,
    st: &mut St,
) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::USHL_asisdsame_only;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 0) & 0x1f;
    let s2: u128 = (w >> 5) & 0x1f;
    let s3: u128 = (w >> 16) & 0x1f;
    let s4: i128 = s1 as i128;
    let s5: i128 = s2 as i128;
    let s6: i128 = s3 as i128;
    let v7 = st.v_read(b, s5 as u32, 64);
    let v8 = st.v_read(b, s6 as u32, 64);
    let v9 = b.zext(v7, Width::W128);
    let v10 = b.extract(v8, 0, Width::new(8));
    let v11 = b.sext(v10, Width::W128);
    let v12 = b.konst(Width::new(128), 0u128);
    let v13 = b.cmp(CmpOp::Sle, v12, v11);
    let v14 = rt::shl_int_ir(b, v9, v11);
    let v16 = b.konst(Width::new(128), 0u128);
    let v17 = b.bin(BinOp::Sub, v16, v11);
    let v18 = b.bin(BinOp::AShr, v9, v17);
    let v19 = b.select(v13, v14, v18);
    let v20 = b.extract(v19, 0, Width::new(64));
    st.v_set(b, s4 as u32, v20, None);
    Ok(())
}

